content.verifier:tests/meta/config.json:
{
  "allow_create": false,
  "rigorous_codebase": true,
  "seeds": [
    42
  ],
  "data_deps_include": [
    "headroute-model",
    "kvbits-dev"
  ],
  "data_deps": [
    {
      "name": "kvbits-dev",
      "description": "DEVELOPMENT split baked into the image (LongBench HotpotQA/2WikiMQA/MultiFieldQA-en/GovReport/PassageRetrieval-en, LongEval 680 lines); the scored items are held out (holdout/llm-kv-precision-vs-count)",
      "host_path": "{data_root}/kvbits_dev",
      "container_path": "/data/kvbits_dev",
      "ready_files": [
        "{data_root}/kvbits_dev/.complete",
        "{data_root}/kvbits_dev/longbench/hotpotqa.jsonl",
        "{data_root}/kvbits_dev/lines/680_lines.jsonl"
      ],
      "prepare": "vendor/data_scripts/transformers-rope-lab/prepare_kvbits_bench.py"
    }
  ],
  "test_cmds": [
    {
      "cmd": "scripts/longbench.sh",
      "label": "longbench",
      "group": 1,
      "compute": 1.0,
      "time": "12:00:00",
      "package": "transformers-rope-lab"
    },
    {
      "cmd": "scripts/lines.sh",
      "label": "lines",
      "group": 1,
      "compute": 1.0,
      "time": "06:00:00",
      "package": "transformers-rope-lab"
    },
    {
      "cmd": "scripts/lbcode.sh",
      "label": "lbcode",
      "group": 1,
      "compute": 1.0,
      "time": "10:00:00",
      "package": "transformers-rope-lab"
    }
  ],
  "baselines": {
    "evict_fp16": {
      "edit_ops": "edits/evict_fp16.edit.py"
    },
    "evict_int8": {
      "edit_ops": "edits/evict_int8.edit.py"
    },
    "evict_int4": {
      "edit_ops": "edits/evict_int4.edit.py"
    },
    "evict_int2": {
      "edit_ops": "edits/evict_int2.edit.py"
    },
    "kivi2": {
      "edit_ops": "edits/kivi2.edit.py"
    },
    "zipcache": {
      "edit_ops": "edits/zipcache.edit.py"
    }
  },
  "files": [
    {
      "filename": "transformers-rope-lab/kv_lab/custom_bits.py",
      "read": [
        {
          "start": 1,
          "end": -1
        }
      ],
      "edit": [
        {
          "start": 110,
          "end": 134
        }
      ]
    },
    {
      "filename": "transformers-rope-lab/kv_lab/emit_bits.py",
      "read": [
        {
          "start": 1,
          "end": -1
        }
      ]
    },
    {
      "filename": "transformers-rope-lab/kv_lab/eval_kvbits.py",
      "read": [
        {
          "start": 1,
          "end": -1
        }
      ]
    }
  ],
  "harbor_extra_docker_steps": [
    "rm -rf /opt/kvbits_trusted && mkdir -p /opt/kvbits_trusted && cp -a /workspace/transformers-rope-lab/src/transformers /opt/kvbits_trusted/transformers && cp /workspace/transformers-rope-lab/kv_lab/eval_kvbits.py /workspace/transformers-rope-lab/kv_lab/emit_bits.py /opt/kvbits_trusted/ && find /opt/kvbits_trusted -name __pycache__ -prune -exec rm -rf {} + && chown -R root:root /opt/kvbits_trusted && chmod -R a-w,a+rX /opt/kvbits_trusted && python -I -S -B -c \"import sys, sysconfig; sys.path[:0] = ['/opt/kvbits_trusted']; sys.path += [sysconfig.get_paths()['purelib'], sysconfig.get_paths()['platlib']]; import transformers; assert transformers.__file__.startswith('/opt/kvbits_trusted/'), transformers.__file__; print('trusted transformers', transformers.__version__)\"",
    "rm -rf /root/.cache/huggingface /data/headroute/model/.cache && python -I -S -B /opt/kvbits_trusted/eval_kvbits.py --scan-image /"
  ],
  "harbor_extra_docker_steps_position": "end",
  "_harbor_extra_docker_steps_note": "Copies the fixed evaluator and the transformers source it imports to a root-owned, read-only /opt/kvbits_trusted at build time, so a rule executed earlier in the same eval (same uid) cannot rewrite the code the trusted evaluator runs; the run scripts exec it by absolute path after a pinned sha256 check.",
  "ephemeral_inputs": true,
  "ephemeral_inputs_transport": "stdin",
  "harbor_allow_internet": false,
  "_harbor_allow_internet_note": "Sealed trial: the model, the development split and the pip environment are baked at build; the scored items arrive from the verifier. A networked trial could download the public LongBench/LongEval test files and precompute per-document plans.",
  "harbor_trusted_result": true,
  "_harbor_trusted_result_note": "the rule runs once per batch through $MLSBENCH_RUN_UNTRUSTED (fresh uid) behind the fixed driver's Landlock allow-list; the root evaluator (/opt/kvbits_trusted, digest-pinned, $MLSBENCH_TRUSTED_PYTHON) appends the score to MLSBENCH_RESULT_FILE, which the verifier parses"
}
